async function liveReplay(ctx, r, urls, label) {
  const rows = urls.map(u => { try { const x = /^https?:\/\//.test(u) ? new URL(u) : new URL(u, ctx.base); return x.pathname + x.search; } catch { return null; } }).filter(Boolean);
  const uniq = [...new Set(rows)];
  let lost = 0, chained = 0, ok = 0;
  await pool(uniq, ctx.concurrency, async (p) => {
    const res = await resolveHops(ctx.base + p, ctx.base, { timeoutMs: ctx.timeoutMs });
    if (res.status !== 200) { lost++; finding(r, 'error', `LOST   ${p}  ->  ${res.status}${res.trail.length ? '  via ' + res.trail.map(t => t.replace(ctx.base, '')).join(' -> ') : ''}`); }
    else if (res.hops > 1) { chained++; finding(r, 'error', `CHAIN  ${p}  ->  ${res.trail.map(t => t.replace(ctx.base, '')).join(' -> ')}  (${res.hops} hops)`); }
    else ok++;
  });
  r.summary.push(`${label}: ${uniq.length} legacy URLs replayed against ${ctx.base} · ok: ${ok} · chains: ${chained} · lost: ${lost}`);
  r.stats.live = { replayed: uniq.length, ok, chained, lost };
}

